        if (scanf("%x %x %d", &occupied, &buckled, &speed) != 3) break;

        occupied |= SEAT_DRIVER;            /* no mat sensor: always occupied */

        int any = 0;
        for (int i = 0; i < SEAT_COUNT; i++) {
            if (seat_unbuckled(occupied, buckled, seats[i])) {
