        int count = 1, ev = -1;
        char *star = strchr(tok, '*');
        if (star) {
            *star = '\0';
            if (sscanf(star + 1, "%d", &count) != 1) return 0;
        }
        if (strncmp(tok, "RAW:", 4) == 0) {
            if (sscanf(tok + 4, "%d", &ev) != 1) return 0;
        } else {
            for (int e = 0; e < CAN_EV_COUNT; e++)
                if (strcmp(tok, h_names[e]) == 0) ev = e;
            if (ev < 0) return 0;
