            idx++;
            CanErrState before = node.state;
            CanErrState r = can_fc_event(&node, ev);
            if (r != node.state) { printf("%d BAD RETURN VALUE\n", idx); return 0; }
            if (r != before)
                printf("%d %s -> %s TEC=%d REC=%d\n", idx, h_st(before), h_st(r), node.tec, node.rec);
